CREATE   PROCEDURE [synapse_fo].[usp_Update_VENDPACKINGSLIPTRANS]
AS
BEGIN

	UPDATE tgt SET
		tgt.[sinkcreatedon] = src.[sinkcreatedon],
		tgt.[SinkModifiedOn] = src.[SinkModifiedOn],
		tgt.[fullymatched] = src.[fullymatched],
		tgt.[inventreftype] = src.[inventreftype],
		tgt.[stockedproduct] = src.[stockedproduct],
		tgt.[sysdatastatecode] = src.[sysdatastatecode],
		tgt.[destcountryregionid] = src.[destcountryregionid],
		tgt.[acceptedqty_in] = src.[acceptedqty_in],
		tgt.[accountingdate] = src.[accountingdate],
		tgt.[costledgervoucher] = src.[costledgervoucher],
		tgt.[currencycode_w] = src.[currencycode_w],
		tgt.[defaultdimension] = src.[defaultdimension],
		tgt.[destcounty] = src.[destcounty],
		tgt.[deviationqty_ru] = src.[deviationqty_ru],
		tgt.[exciseamount_ru] = src.[exciseamount_ru],
		tgt.[excisevalue_ru] = src.[excisevalue_ru],
		tgt.[externalitemid] = src.[externalitemid],
		tgt.[intercompanyinventtransid] = src.[intercompanyinventtransid],
		tgt.[inventdate] = src.[inventdate],
		tgt.[inventdimid] = src.[inventdimid],
		tgt.[inventqty] = src.[inventqty],
		tgt.[inventrefid] = src.[inventrefid],
		tgt.[inventreftransid] = src.[inventreftransid],
		tgt.[inventtransid] = src.[inventtransid],
		tgt.[itemid] = src.[itemid],
		tgt.[lineamount_w] = src.[lineamount_w],
		tgt.[linenum] = src.[linenum],
		tgt.[name] = src.[name],
		tgt.[ngpcodestable_fr] = src.[ngpcodestable_fr],
		tgt.[ordered] = src.[ordered],
		tgt.[origcountryregionid] = src.[origcountryregionid],
		tgt.[origpurchid] = src.[origpurchid],
		tgt.[origstateid] = src.[origstateid],
		tgt.[packingslipid] = src.[packingslipid],
		tgt.[pdscwordered] = src.[pdscwordered],
		tgt.[pdscwqty] = src.[pdscwqty],
		tgt.[pdscwremain] = src.[pdscwremain],
		tgt.[port] = src.[port],
		tgt.[priceunit] = src.[priceunit],
		tgt.[procurementcategory] = src.[procurementcategory],
		tgt.[purchaselineexpecteddeliverydate] = src.[purchaselineexpecteddeliverydate],
		tgt.[purchaselinelinenumber] = src.[purchaselinelinenumber],
		tgt.[purchunit] = src.[purchunit],
		tgt.[qty] = src.[qty],
		tgt.[reasontableref] = src.[reasontableref],
		tgt.[receivedqty_in] = src.[receivedqty_in],
		tgt.[rejectedqty_in] = src.[rejectedqty_in],
		tgt.[remain] = src.[remain],
		tgt.[remaininvent] = src.[remaininvent],
		tgt.[returnactionid] = src.[returnactionid],
		tgt.[sourcedocumentline] = src.[sourcedocumentline],
		tgt.[statisticvalue_lt] = src.[statisticvalue_lt],
		tgt.[statprocid] = src.[statprocid],
		tgt.[taxamount_ru] = src.[taxamount_ru],
		tgt.[taxgroup_ru] = src.[taxgroup_ru],
		tgt.[transactioncode] = src.[transactioncode],
		tgt.[transport] = src.[transport],
		tgt.[valuemst] = src.[valuemst],
		tgt.[vatamount_ru] = src.[vatamount_ru],
		tgt.[vatvalue_ru] = src.[vatvalue_ru],
		tgt.[vendpackingslipjour] = src.[vendpackingslipjour],
		tgt.[weight] = src.[weight],
		tgt.[workerpurchaser] = src.[workerpurchaser],
		tgt.[itemcodeid] = src.[itemcodeid],
		tgt.[cancelledqty] = src.[cancelledqty],
		tgt.[modifiedon] = src.[modifiedon],
		tgt.[modifiedby] = src.[modifiedby],
		tgt.[createdon] = src.[createdon],
		tgt.[createdby] = src.[createdby],
		tgt.[IsDelete] = src.[IsDelete]
	FROM [synapse_fo].[VENDPACKINGSLIPTRANS] tgt
		INNER JOIN [staging_fo].[VENDPACKINGSLIPTRANS] src
			ON tgt.[RecId] = src.[RecId]
			AND tgt.[DataAreaId] = src.[DataAreaId]
END
